<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ValueObject\ConsentPurposeKeyVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeKeyOptions;

trait ConsentPurposeKeyAccessor
{
    private ConsentPurposeKeyVO $_key;
    public function getKey(): ConsentPurposeKeyOptions
    {
        return $this->_key->value();
    }
    public function key(): ConsentPurposeKeyVO
    {
        return $this->_key;
    }
    public function isKeyChanged(?self $original = null): bool
    {
        return !$this->_key->equals($original?->_key);
    }
    public function withKey(ConsentPurposeKeyVO|ConsentPurposeKeyOptions $key): self
    {
        $copy = clone $this;
        $copy->_key = ConsentPurposeKeyVO::from($key);
        return $copy;
    }
}
